"""Return an ordered keep mask and one finite margin per proposed call."""
# validate all inputs
for arr in [logp_with_result, logp_call_only, logp_no_call]:
    if not isinstance(arr, np.ndarray):
        raise ValueError("All log probability arrays must be numpy ndarrays")
if logp_with_result.ndim != 2 or logp_call_only.ndim != 2 or logp_no_call.ndim != 2:
    raise ValueError("All log probability arrays must be 2D matrices")
if logp_with_result.shape != logp_call_only.shape or logp_call_only.shape != logp_no_call.shape:
    raise ValueError("All log probability arrays must have the same shape")
if logp_with_result.size == 0:
    raise ValueError("Log probability arrays cannot be empty")
for arr in [logp_with_result, logp_call_only, logp_no_call]:
    if not np.all(np.isfinite(arr)):
        raise ValueError("All log probabilities must be finite")
    if np.any(arr > 0):
        raise ValueError("All log probabilities must be nonpositive")
if isinstance(tau_filter, bool):
    raise ValueError("tau_filter must not be a boolean")
if not np.issubdtype(type(tau_filter), np.floating) and not isinstance(tau_filter, (int, float)):
    raise ValueError("tau_filter must be a finite nonnegative number")
if not np.isfinite(tau_filter):
    raise ValueError("tau_filter must be finite")
if tau_filter < 0:
    raise ValueError("tau_filter must be nonnegative")
n_candidates, F = logp_with_result.shape
t = np.arange(F)
raw_weights = np.maximum(0, 1 - 0.2 * t)
normalized_weights = raw_weights / np.sum(raw_weights)
L_plus = -np.sum(normalized_weights * logp_with_result, axis=1)
L_call_only = -np.sum(normalized_weights * logp_call_only, axis=1)
L_no_call = -np.sum(normalized_weights * logp_no_call, axis=1)
L_minus = np.minimum(L_no_call, L_call_only)
margins = L_minus - L_plus
keep_mask = margins >= tau_filter
return keep_mask, margins
